package com.estateflow.dao.jdbc;
import com.estateflow.dao.WorkOrderDao;import com.estateflow.db.DatabaseManager;import com.estateflow.model.*;import com.estateflow.model.enums.MaintenancePriority;import java.sql.*;import java.time.*;import java.util.*;
public final class JdbcWorkOrderDao extends BaseJdbcDao implements WorkOrderDao{
 private static final String COL="work_order_id,property_id,maintenance_request_id,vendor_id,expense_id,title,scope,priority,due_date,status,estimated_cost,actual_cost,completion_notes,created_by,created_at,updated_at,completed_at";
 private static final RowMapper<WorkOrder> MAP=rs->new WorkOrder(rs.getLong("work_order_id"),rs.getLong("property_id"),longOrNull(rs,"maintenance_request_id"),longOrNull(rs,"vendor_id"),longOrNull(rs,"expense_id"),rs.getString("title"),rs.getString("scope"),MaintenancePriority.valueOf(rs.getString("priority")),date(rs,"due_date"),WorkOrderStatus.valueOf(rs.getString("status")),rs.getBigDecimal("estimated_cost"),rs.getBigDecimal("actual_cost"),rs.getString("completion_notes"),longOrNull(rs,"created_by"),dateTime(rs,"created_at"),dateTime(rs,"updated_at"),dateTime(rs,"completed_at"));
 public JdbcWorkOrderDao(DatabaseManager db){super(db);}
 @Override public boolean isAvailable(){return exists("check work order table","SELECT 1 FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name='work_order'",Binder.NONE);}
 @Override public WorkOrder insert(WorkOrder w){long id=insertReturningKey("insert work order","INSERT INTO work_order(property_id,maintenance_request_id,title,scope,priority,due_date,status,estimated_cost,created_by) VALUES(?,?,?,?,?,?,'DRAFT',?,?)",ps->{ps.setLong(1,w.propertyId());nullable(ps,2,w.maintenanceRequestId());ps.setString(3,w.title());ps.setString(4,w.scope());ps.setString(5,w.priority().name());date(ps,6,w.dueDate());ps.setBigDecimal(7,w.estimatedCost());nullable(ps,8,w.createdBy());});return find(id).orElseThrow();}
 @Override public int update(WorkOrder w){return executeUpdate("update work order","UPDATE work_order SET title=?,scope=?,priority=?,due_date=?,estimated_cost=?,actual_cost=?,completion_notes=? WHERE work_order_id=? AND status IN ('DRAFT','ASSIGNED')",ps->{ps.setString(1,w.title());ps.setString(2,w.scope());ps.setString(3,w.priority().name());date(ps,4,w.dueDate());ps.setBigDecimal(5,w.estimatedCost());ps.setBigDecimal(6,w.actualCost());ps.setString(7,w.completionNotes());ps.setLong(8,w.id());});}
 @Override public Optional<WorkOrder> find(long id){return queryOne("find work order","SELECT "+COL+" FROM work_order WHERE work_order_id=?",ps->ps.setLong(1,id),MAP);}
 @Override public List<WorkOrderRow> search(Long property,Long vendor,WorkOrderStatus status,MaintenancePriority priority,LocalDate from,LocalDate to,boolean overdue,LocalDate today){StringBuilder q=new StringBuilder("SELECT w.work_order_id,p.name property_name,v.name vendor_name,w.maintenance_request_id,w.title,w.priority,w.due_date,w.status,w.estimated_cost,w.actual_cost,w.expense_id FROM work_order w JOIN property p ON p.property_id=w.property_id LEFT JOIN maintenance_vendor v ON v.vendor_id=w.vendor_id WHERE (? IS NULL OR w.property_id=?) AND (? IS NULL OR w.vendor_id=?) AND (? IS NULL OR w.status=?) AND (? IS NULL OR w.priority=?) AND (? IS NULL OR w.due_date>=?) AND (? IS NULL OR w.due_date<=?) ");if(overdue)q.append("AND w.due_date<? AND w.status IN ('DRAFT','ASSIGNED','IN_PROGRESS') ");q.append("ORDER BY CASE WHEN w.due_date<? AND w.status IN ('DRAFT','ASSIGNED','IN_PROGRESS') THEN 0 ELSE 1 END,w.due_date,w.work_order_id DESC LIMIT 1000");return queryList("search work orders",q.toString(),ps->{int i=1;nullable(ps,i++,property);nullable(ps,i++,property);nullable(ps,i++,vendor);nullable(ps,i++,vendor);text(ps,i++,status==null?null:status.name());text(ps,i++,status==null?null:status.name());text(ps,i++,priority==null?null:priority.name());text(ps,i++,priority==null?null:priority.name());date(ps,i++,from);date(ps,i++,from);date(ps,i++,to);date(ps,i++,to);if(overdue)date(ps,i++,today);date(ps,i,today);},rs->new WorkOrderRow(rs.getLong("work_order_id"),rs.getString("property_name"),rs.getString("vendor_name"),longOrNull(rs,"maintenance_request_id"),rs.getString("title"),MaintenancePriority.valueOf(rs.getString("priority")),date(rs,"due_date"),WorkOrderStatus.valueOf(rs.getString("status")),rs.getBigDecimal("estimated_cost"),rs.getBigDecimal("actual_cost"),longOrNull(rs,"expense_id")));}
 @Override public List<com.estateflow.dto.AdvancedAnalyticsReport.VendorPerformance> vendorPerformance(LocalDate from,LocalDate to){return queryList("summarize vendor work-order performance","SELECT v.vendor_id,v.name,COUNT(*) AS completed_orders,SUM(CASE WHEN w.due_date IS NOT NULL THEN 1 ELSE 0 END) AS due_dated_orders,SUM(CASE WHEN w.due_date IS NOT NULL AND DATE(w.completed_at)<=w.due_date THEN 1 ELSE 0 END) AS on_time_orders,COALESCE(SUM(w.actual_cost),0) AS actual_cost,AVG(DATEDIFF(DATE(w.completed_at),DATE(w.created_at))) AS average_days FROM work_order w JOIN maintenance_vendor v ON v.vendor_id=w.vendor_id WHERE w.status='COMPLETED' AND w.completed_at>=? AND w.completed_at<? GROUP BY v.vendor_id,v.name ORDER BY completed_orders DESC,v.name",ps->{ps.setObject(1,from.atStartOfDay());ps.setObject(2,to.plusDays(1).atStartOfDay());},rs->{int count=rs.getInt("completed_orders"),onTime=rs.getInt("on_time_orders"),dueDated=rs.getInt("due_dated_orders");java.math.BigDecimal average=rs.getBigDecimal("average_days");return new com.estateflow.dto.AdvancedAnalyticsReport.VendorPerformance(rs.getLong("vendor_id"),rs.getString("name"),count,onTime,dueDated,dueDated==0?java.math.BigDecimal.ZERO:java.math.BigDecimal.valueOf(onTime*100L).divide(java.math.BigDecimal.valueOf(dueDated),2,java.math.RoundingMode.HALF_UP),rs.getBigDecimal("actual_cost"),average==null?java.math.BigDecimal.ZERO:average.setScale(1,java.math.RoundingMode.HALF_UP));});}
 @Override public int transition(long id,WorkOrderStatus expected,WorkOrderStatus status,LocalDateTime completed,String notes){return executeUpdate("transition work order","UPDATE work_order SET status=?,completed_at=?,completion_notes=? WHERE work_order_id=? AND status=?",ps->{ps.setString(1,status.name());ps.setObject(2,completed);ps.setString(3,notes);ps.setLong(4,id);ps.setString(5,expected.name());});}
 @Override public int complete(long id,WorkOrderStatus expected,java.math.BigDecimal actual,String notes,LocalDateTime completed){return executeUpdate("complete work order","UPDATE work_order SET status='COMPLETED',actual_cost=?,completion_notes=?,completed_at=? WHERE work_order_id=? AND status=?",ps->{ps.setBigDecimal(1,actual);ps.setString(2,notes);ps.setObject(3,completed);ps.setLong(4,id);ps.setString(5,expected.name());});}
 @Override public int assign(long id,long vendor){return executeUpdate("assign vendor to work order","UPDATE work_order SET vendor_id=?,status='ASSIGNED' WHERE work_order_id=? AND status='DRAFT'",ps->{ps.setLong(1,vendor);ps.setLong(2,id);});}
 @Override public int linkExpense(long id,long expense){return executeUpdate("link expense to work order","UPDATE work_order SET expense_id=? WHERE work_order_id=? AND expense_id IS NULL",ps->{ps.setLong(1,expense);ps.setLong(2,id);});}
 private static void nullable(PreparedStatement p,int i,Long x)throws SQLException{if(x==null)p.setNull(i,Types.BIGINT);else p.setLong(i,x);}private static void text(PreparedStatement p,int i,String x)throws SQLException{if(x==null)p.setNull(i,Types.VARCHAR);else p.setString(i,x);}private static void date(PreparedStatement p,int i,LocalDate x)throws SQLException{if(x==null)p.setNull(i,Types.DATE);else p.setObject(i,x);}
}
